<template><section><div class="rounded-3xl bg-indigo-600 p-8 text-white"><p class="font-bold uppercase tracking-wider text-indigo-200">Your account</p><h1 class="mt-2 text-4xl font-black">Shop as a customer. Become an affiliate when you want.</h1><p class="mt-3 max-w-2xl text-indigo-100">There is no separate affiliate account. Your existing MarketFlow account can do both.</p><button v-if="!user?.isAffiliate" @click="enable" class="mt-6 rounded-xl bg-white px-5 py-3 font-bold text-indigo-700">Enable affiliate marketing</button><p v-else class="mt-6 inline-block rounded-xl bg-white/15 px-5 py-3 font-bold">Affiliate marketing is enabled on this account</p></div><h2 class="mt-10 text-xl font-black">Available programs</h2><div class="mt-4 grid gap-4 md:grid-cols-2"><div v-for="p in programs" :key="p.id" class="rounded-2xl border bg-white p-5"><b>{{p.name}}</b><p class="mt-2 text-slate-500">{{p.commissionType==='percentage'?p.commissionRate+'% commission':'Fixed commission'}}</p></div></div></section></template><script>import api from'../services/api';import{auth,setAuth}from'../stores';export default{data(){return{programs:[],user:auth.user,error:''}},async mounted(){try{const r=await api.get('/affiliate-programs');this.programs=r.data.data||r.data.programs||[]}catch{}},methods:{async enable(){try{const r=await api.post('/auth/affiliate/enable');this.user=r.data.data?.user||r.data.user;setAuth(this.user)}catch(e){this.error=e.response?.data?.message||'Unable to enable affiliate marketing'}}}}</script>